import { readFileSync, writeFileSync } from 'node:fs';
import { test } from 'vitest';
import GBNF from 'gbnf';

interface Case {
  grammar: string;
  initial: string;
  adds: string[];
}

const describeError = (err: unknown) => ({
  error: (err as Error).name,
  message: (err as Error).message,
});

const run = (testCase: Case) => {
  const steps: unknown[] = [];
  let state;
  try {
    state = GBNF(testCase.grammar, testCase.initial);
  } catch (err) {
    return { init: describeError(err), steps };
  }
  const init = {
    rules: [...state].map((rule) => JSON.stringify(rule)),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    graph: (state as any).graph.print(),
  };
  for (const add of testCase.adds) {
    try {
      state = state.add(add);
    } catch (err) {
      steps.push(describeError(err));
      break;
    }
    steps.push({ rules: [...state].map((rule) => JSON.stringify(rule)) });
  }
  return { init, steps };
};

test('dump', () => {
  const cases: Case[] = JSON.parse(readFileSync('/tmp/diff/cases.json', 'utf8'));
  writeFileSync('/tmp/diff/ts.json', JSON.stringify(cases.map(run), null, 1));
});

